INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(3950, 'licensing agreement', '/ˈlaɪsənsɪŋ əˈɡriːmənt/', 'noun', '{"zh-TW":["授權協議；許可協議"],"en":["a contract granting permission to use intellectual property"]}', NULL, 'sign a licensing agreement / licensing agreement terms', '[{"en":"The company signed a licensing agreement with a foreign manufacturer.","zh-TW":"公司與一家外國製造商簽署了授權協議。"},{"en":"Royalties under the licensing agreement are paid quarterly.","zh-TW":"授權協議下的版稅每季支付。"}]', NULL, NULL, 5, 3950, NULL),
(3951, 'licensing fee', '/ˈlaɪsənsɪŋ fiː/', 'noun', '{"zh-TW":["授權費；許可費"],"en":["a payment made for the right to use someone else''s intellectual property or technology"]}', NULL, 'charge a licensing fee / licensing fee structure', '[{"en":"The software company charges an annual licensing fee per user.","zh-TW":"軟件公司按每個用戶收取年度授權費。"},{"en":"A one-time licensing fee grants perpetual use rights to the buyer.","zh-TW":"一次性授權費向買方授予永久使用權。"}]', NULL, NULL, 5, 3951, NULL),
(3952, 'lie', 'laɪ', 'verb', '{"zh-TW":["位於；躺","撒謊"],"en":["to be situated in a place","to say something untrue"]}', NULL, 'lie in/about', '[{"en":"The solution lies in better communication.","zh-TW":"解決方案在於更好的溝通。"}]', '{"noun":"lie, liar"}', NULL, 1, 3952, NULL),
(3953, 'lien', '/liːn/', 'noun', '{"zh-TW":["留置權；扣押權"],"en":["the right to keep possession of property until a debt is paid"]}', NULL, 'place a lien / file a lien / mechanic''s lien', '[{"en":"The contractor placed a lien on the property due to unpaid bills.","zh-TW":"承包商因未付帳款對財產設置了留置權。"},{"en":"A lien must be paid off before the property can be sold.","zh-TW":"留置權必須在財產出售之前清償。"}]', '{"verb":"lien"}', NULL, 1, 3953, NULL),
(3954, 'life', '/laɪf/', 'noun', '{"zh-TW":["生命；生活"],"en":["the existence of a person","the way someone lives"]}', NULL, 'work-life balance / shelf life', '[{"en":"Work-life balance is important to us.","zh-TW":"工作與生活的平衡對我們很重要。"},{"en":"The product has a shelf life of two years.","zh-TW":"產品的保質期為兩年。"}]', '{"noun":"life","adjective":"lifelong","noun2":"lifestyle","noun3":"lifetime"}', NULL, 1, 3954, NULL),
(3955, 'life cycle', '/laɪf ˈsaɪkəl/', 'noun', '{"zh-TW":["生命週期"],"en":["the series of stages a product or organism goes through from creation to end"]}', NULL, 'product life cycle / life cycle stage / life cycle management', '[{"en":"Understanding the product life cycle helps plan marketing strategies.","zh-TW":"了解產品生命週期有助於規劃行銷策略。"},{"en":"Technologies often follow a predictable life cycle from introduction to obsolescence.","zh-TW":"技術通常遵循從引入到過時的可預測生命週期。"}]', NULL, NULL, 4, 3955, NULL),
(3956, 'life cycle assessment', '/laɪf ˈsaɪkəl əˈsesmənt/', 'noun', '{"zh-TW":["生命週期評估"],"en":["an analysis of the environmental impact of a product through its entire life"]}', NULL, 'conduct life cycle assessment / life cycle assessment methodology / life cycle assessment results', '[{"en":"A life cycle assessment measures environmental impact from production to disposal.","zh-TW":"生命週期評估測量從生產到處置的環境影響。"},{"en":"Companies use life cycle assessment to identify the most impactful stages.","zh-TW":"公司使用生命週期評估來識別影響最大的階段。"}]', NULL, NULL, 5, 3956, NULL),
(3957, 'light', '/laɪt/', 'noun', '{"zh-TW":["【主要意義-名詞】光；燈光","【次要意義-形容詞】輕的；輕量的","【次要意義-形容詞】淺色的；明亮的","【次要意義-形容詞】不嚴格的；輕描淡寫的","【次要意義-副詞】輕裝地；只帶少量行李"],"en":["[primary - noun] electromagnetic radiation that makes things visible","[secondary - adjective] not heavy in weight","[secondary - adjective] pale in color","[secondary - adjective] not serious or severe","[secondary - adverb] with little luggage"]}', NULL, 'light sentence / light duties / travel light / light reading / in a new light', '[{"en":"The judge gave a surprisingly light sentence for the financial crime.","zh-TW":"法官對這起金融犯罪給予了出人意料的輕判。"},{"en":"Employees on light duties are assigned simpler administrative tasks.","zh-TW":"輕度工作的員工被分配較簡單的行政任務。"},{"en":"Business travelers prefer to travel light for short trips.","zh-TW":"商務旅客短途出行時更喜歡輕裝上陣。"}]', '{"noun":"lighting, lightness","verb":"lighten","adjective":"lightweight"}', 'light 作形容詞有多個次要意義：「不嚴格的」（light sentence）、「輕量的」（light duties）等，片語 in a new light = 以新眼光看待，常見於 TOEIC 描述判決或職責的語境。', 2, 3957, NULL),
(3958, 'lightning', '/ˈlaɪtnɪŋ/', 'noun', '{"zh-TW":["閃電"],"en":["a flash of bright light in the sky during a storm"]}', '{"root":{"text":"light","meaning":"light (光)"},"suffix":{"text":"-ning","meaning":"action (動作)"},"logic":"天空中光的動作，即「閃電」。"}', 'lightning bolt / lightning strike / lightning rod', '[{"en":"Lightning struck the old tree in the park.","zh-TW":"閃電擊中了公園裡的老樹。"},{"en":"Never stand under a tree during a lightning storm.","zh-TW":"閃電暴風雨時千萬不要站在樹下。"}]', NULL, NULL, 3, 3958, NULL),
(3959, 'likewise', '/ˈlaɪkwaɪz/', 'adverb', '{"zh-TW":["同樣地；也"],"en":["in the same way; also"]}', NULL, 'do likewise / likewise, ...', '[{"en":"The first team finished early, and the second did likewise.","zh-TW":"第一組提前完成了，第二組也是如此。"},{"en":"Likewise, we must consider the long-term effects.","zh-TW":"同樣地，我們必須考慮長期影響。"}]', '{"adverb":"likewise"}', NULL, 3, 3959, NULL),
(3960, 'limit', '/ˈlɪmɪt/', 'noun, verb', '{"zh-TW":["限制；限度"],"en":["a boundary or restriction"]}', NULL, 'set/impose a limit / speed limit / within limits', '[{"en":"There is a limit to what we can achieve in one day.","zh-TW":"我們一天能完成的事情有限。"},{"en":"The government imposed limits on imports.","zh-TW":"政府對進口實施了限制。"}]', '{"noun":"limit, limitation","verb":"limit","adjective":"limited, limitless"}', NULL, 2, 3960, 150),
(3961, 'limit order', '/ˈlɪmɪt ˈɔːrdər/', 'noun', '{"zh-TW":["限價訂單"],"en":["an order to buy or sell a security at a specific or better price"]}', NULL, 'place a limit order / execute a limit order', '[{"en":"He placed a limit order to buy the stock at 50 dollars.","zh-TW":"他下了一個在50元買入股票的限價訂單。"},{"en":"A limit order protects against buying at an unfavorable price.","zh-TW":"限價訂單防止以不利的價格購買。"}]', '{"opposite":"market order"}', NULL, 4, 3961, NULL),
(3962, 'limited', 'ˈlɪmɪtɪd', 'adjective', '{"zh-TW":["有限的；受限的","少量的"],"en":["restricted in size or extent","few or small"]}', NULL, 'limited time/limited resources', '[{"en":"We have limited time to complete this.","zh-TW":"我們完成這件事的時間有限。"}]', '{"verb":"limit","noun":"limitation","adverb":"limitedly"}', NULL, 3, 3962, NULL),
(3963, 'limited liability', '/ˈlɪmɪtɪd ˌlaɪəˈbɪlɪti/', 'noun', '{"zh-TW":["有限責任"],"en":["a legal principle limiting a shareholder''s financial risk to the amount invested"]}', NULL, 'protected by limited liability / limited liability company', '[{"en":"Shareholders enjoy limited liability and cannot lose more than their investment.","zh-TW":"股東享有有限責任，不能損失超過其投資額。"},{"en":"The limited liability structure encourages entrepreneurship and risk-taking.","zh-TW":"有限責任結構鼓勵企業家精神和承擔風險。"}]', '{"abbreviation":"Ltd","synonym":"limited liability company"}', NULL, 5, 3963, NULL),
(3964, 'limited liability company', '/ˈlɪmɪtɪd laɪəˈbɪlɪti ˈkʌmpəni/', 'noun', '{"zh-TW":["有限責任公司"],"en":["a business structure where owners are not personally liable for company debts"]}', NULL, 'form a limited liability company / LLC structure', '[{"en":"She incorporated a limited liability company to protect personal assets.","zh-TW":"她設立了有限責任公司以保護個人資產。"},{"en":"A limited liability company combines partnership flexibility with corporate protection.","zh-TW":"有限責任公司將合夥靈活性與公司保護相結合。"}]', '{"abbreviation":"LLC"}', NULL, 5, 3964, NULL),
(3965, 'limited partnership', '/ˈlɪmɪtɪd ˈpɑːrtnərʃɪp/', 'noun', '{"zh-TW":["有限合夥企業"],"en":["a business structure with both general and limited partners having different liability levels"]}', NULL, 'form a limited partnership / limited partnership agreement', '[{"en":"The investment vehicle was structured as a limited partnership.","zh-TW":"投資工具被構建為有限合夥企業。"},{"en":"Limited partners have liability only up to their investment in the fund.","zh-TW":"有限合夥人的責任僅限於其在基金中的投資額。"}]', '{"abbreviation":"LP"}', NULL, 5, 3965, NULL),
(3966, 'line', '/laɪn/', 'noun', '{"zh-TW":["線；排；產品線"],"en":["a long narrow mark; a row of people; a range of products"]}', NULL, 'product line / bottom line / assembly line', '[{"en":"The company expanded its product line.","zh-TW":"公司擴大了其產品線。"},{"en":"The bottom line is that we need more revenue.","zh-TW":"重點是我們需要更多收入。"}]', '{"noun":"line","verb":"line","adjective":"linear"}', NULL, 1, 3966, NULL),
(3967, 'line manager', '/laɪn ˈmænɪdʒər/', 'noun', '{"zh-TW":["直屬主管；直線管理人"],"en":["the manager directly responsible for supervising an employee''s work"]}', NULL, 'report to the line manager / line manager responsibilities', '[{"en":"All performance feedback is channeled through the line manager.","zh-TW":"所有績效反饋都通過直屬主管傳達。"},{"en":"She discussed the promotion opportunity with her line manager.","zh-TW":"她與直屬主管討論了晉升機會。"}]', NULL, NULL, 4, 3967, NULL),
(3968, 'line of credit', '/laɪn əv ˈkredɪt/', 'noun', '{"zh-TW":["信用額度"],"en":["a pre-approved borrowing limit from a bank that can be drawn on as needed"]}', NULL, 'draw on a line of credit / revolving line of credit / secure a line of credit', '[{"en":"The company used its line of credit to cover seasonal cash shortfalls.","zh-TW":"公司使用信用額度填補季節性現金短缺。"},{"en":"Maintaining an unused line of credit provides financial flexibility.","zh-TW":"保持未使用的信用額度提供財務靈活性。"}]', NULL, NULL, 5, 3968, NULL),
(3969, 'linguistic', '/''lɪŋˈɡwɪstɪk/', 'adjective', '{"zh-TW":["語言的；語言學的"],"en":["relating to language or linguistics"]}', NULL, 'linguistic skill / linguistic ability / linguistic diversity', '[{"en":"Children show remarkable linguistic ability when they are exposed to multiple languages early.","zh-TW":"兒童在早期接觸多種語言時表現出顯著的語言能力。"},{"en":"The country''s linguistic diversity is reflected in its many regional dialects.","zh-TW":"該國的語言多樣性體現在其眾多地區方言中。"}]', '{"noun":"linguistics","noun2":"linguist","adverb":"linguistically"}', NULL, 4, 3969, NULL),
(3970, 'linguistic competence', '/''lɪŋˌɡwɪstɪk ˌkɒmpɪtəns/', 'noun', '{"zh-TW":["語言能力；語言勝任力"],"en":["a person''s underlying knowledge of the rules of a language, enabling them to produce and understand speech"]}', NULL, 'develop linguistic competence / assess linguistic competence / linguistic competence test', '[{"en":"Strong linguistic competence in a second language supports effective professional communication.","zh-TW":"第二語言的強大語言能力支持有效的專業溝通。"},{"en":"The examination assessed the candidates'' linguistic competence in English.","zh-TW":"考試評估了候選人的英語語言能力。"}]', '{"adjective":"linguistically"}', NULL, 5, 3970, NULL),
(3971, 'link', '/lɪŋk/', 'noun, verb', '{"zh-TW":["連結；聯繫"],"en":["a connection between things"]}', NULL, 'link between / link to / a direct link', '[{"en":"There is a clear link between education and income.","zh-TW":"教育和收入之間有明確的關聯。"},{"en":"Please click the link below for more details.","zh-TW":"請點擊下面的連結以獲取更多詳情。"}]', '{"noun":"link, linkage","verb":"link"}', NULL, 1, 3971, NULL),
(3972, 'liquid', '/ˈlɪkwɪd/', 'noun, adjective', '{"zh-TW":["液體","液態的；流動的"],"en":["a substance that flows freely","in the form of a liquid; easily converted to cash"]}', NULL, 'liquid assets / liquid state', '[{"en":"The company needs more liquid assets.","zh-TW":"公司需要更多的流動資產。"},{"en":"Water is a liquid at room temperature.","zh-TW":"水在室溫下是液體。"}]', '{"noun":"liquid, liquidity","adjective":"liquid","verb":"liquidate"}', NULL, 2, 3972, NULL),
(3973, 'liquidate', '/ˈlɪkwɪdeɪt/', 'verb', '{"zh-TW":["清算；變現；結清"],"en":["to convert assets into cash, or to close down a business"]}', NULL, 'liquidate assets / liquidate a company', '[{"en":"The failing company was forced to liquidate its assets.","zh-TW":"陷入困境的公司被迫清算其資產。"},{"en":"They decided to liquidate the subsidiary to focus on core business.","zh-TW":"他們決定清算子公司以專注於核心業務。"}]', '{"noun":"liquidation","adjective":"liquidated"}', NULL, 3, 3973, NULL),
(3974, 'liquidated damages', '/ˈlɪkwɪdeɪtɪd ˈdæmɪdʒɪz/', 'noun', '{"zh-TW":["約定損害賠償金"],"en":["a pre-agreed sum payable as compensation for breach"]}', NULL, 'liquidated damages clause / claim liquidated damages', '[{"en":"The contract includes a liquidated damages clause for late delivery.","zh-TW":"合約包含延遲交貨的約定損害賠償金條款。"},{"en":"Liquidated damages were set at five thousand dollars per day.","zh-TW":"約定損害賠償金設定為每天五千元。"}]', NULL, NULL, 5, 3974, NULL),
(3975, 'liquidation', '/ˌlɪkwɪˈdeɪʃən/', 'noun', '{"zh-TW":["清算；倒閉"],"en":["the winding up of a company and sale of its assets"]}', NULL, 'enter liquidation / voluntary liquidation', '[{"en":"The company entered voluntary liquidation after years of losses.","zh-TW":"公司在多年虧損後進入自願清算。"},{"en":"Assets are distributed to creditors during liquidation.","zh-TW":"在清算期間，資產被分配給債權人。"}]', '{"verb":"liquidate","adjective":"liquidated"}', NULL, 4, 3975, 591),
(3976, 'liquidation value', '/ˌlɪkwɪˈdeɪʃən ˈvæljuː/', 'noun', '{"zh-TW":["清算價值"],"en":["the estimated value of assets if sold quickly in a liquidation scenario"]}', NULL, 'calculate liquidation value / liquidation value basis', '[{"en":"The liquidation value of the company''s assets was significantly below book value.","zh-TW":"公司資產的清算價值顯著低於帳面價值。"},{"en":"Creditors assess liquidation value to estimate recovery in a default scenario.","zh-TW":"債權人評估清算價值以估計違約場景中的追回率。"}]', NULL, NULL, 5, 3976, NULL),
(3977, 'liquidity', '/lɪˈkwɪdɪti/', 'noun', '{"zh-TW":["流動性；變現能力"],"en":["the ease with which assets can be converted to cash"]}', NULL, 'market liquidity / liquidity risk / cash and liquidity', '[{"en":"The company maintains high liquidity to meet short-term obligations.","zh-TW":"公司保持高流動性以履行短期義務。"},{"en":"Liquidity dried up during the financial crisis.","zh-TW":"金融危機期間流動性枯竭。"}]', '{"adjective":"liquid","antonym":"illiquid"}', NULL, 3, 3977, NULL),
(3978, 'liquidity event', '/lɪˈkwɪdɪti ɪˈvent/', 'noun', '{"zh-TW":["流動性事件"],"en":["an occurrence enabling investors to cash out their investment in a company"]}', NULL, 'plan for a liquidity event / major liquidity event', '[{"en":"An IPO is the most common form of liquidity event for startups.","zh-TW":"首次公開招股是初創企業最常見的流動性事件形式。"},{"en":"Early investors were waiting for a liquidity event to realize their gains.","zh-TW":"早期投資者正在等待流動性事件以實現其收益。"}]', NULL, NULL, 5, 3978, NULL),
(3979, 'liquidity management', '/lɪˈkwɪdɪti ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["流動性管理"],"en":["the process of ensuring an organization has enough cash to meet its obligations"]}', NULL, 'improve liquidity management / liquidity management strategy', '[{"en":"Effective liquidity management prevents cash shortfalls.","zh-TW":"有效的流動性管理防止了現金短缺。"},{"en":"The treasury team monitors cash positions daily for liquidity management.","zh-TW":"財務團隊每日監控現金狀況以進行流動性管理。"}]', NULL, NULL, 5, 3979, NULL),
(3980, 'liquidity premium', '/lɪˈkwɪdɪti ˈpriːmiəm/', 'noun', '{"zh-TW":["流動性溢價"],"en":["additional return required by investors for holding illiquid assets"]}', NULL, 'liquidity premium spread / earn the liquidity premium / liquidity premium theory', '[{"en":"Illiquid bonds trade at a discount due to the liquidity premium.","zh-TW":"非流動性債券因流動性溢價而以折扣交易。"},{"en":"The liquidity premium widens during periods of market stress.","zh-TW":"在市場壓力時期，流動性溢價擴大。"}]', NULL, NULL, 5, 3980, NULL),
(3981, 'liquidity ratio', '/lɪˈkwɪdɪti ˈreɪʃiəʊ/', 'noun', '{"zh-TW":["流動比率；流動性比率"],"en":["a financial metric that measures a company''s ability to cover its short-term obligations with its liquid assets"]}', NULL, 'analyze the liquidity ratio / maintain a healthy liquidity ratio / improve the liquidity ratio', '[{"en":"A healthy liquidity ratio indicates that a company can meet its short-term debt obligations.","zh-TW":"健康的流動比率表明公司能夠履行短期債務義務。"},{"en":"The lender required a minimum liquidity ratio before approving the loan application.","zh-TW":"貸款機構在批准貸款申請前要求最低流動比率。"}]', '{"adjective":"liquid","noun":"liquidity"}', NULL, 5, 3981, NULL),
(3982, 'liquidity risk', '/lɪˈkwɪdɪti rɪsk/', 'noun', '{"zh-TW":["流動性風險"],"en":["the risk of not having enough cash to meet short-term obligations"]}', NULL, 'manage liquidity risk / liquidity risk assessment', '[{"en":"A sudden withdrawal triggered a liquidity risk event.","zh-TW":"突然的提款觸發了流動性風險事件。"},{"en":"Maintaining a cash reserve reduces exposure to liquidity risk.","zh-TW":"維持現金儲備降低了對流動性風險的暴露。"}]', NULL, NULL, 5, 3982, NULL),
(3983, 'list', '/lɪst/', 'noun, verb', '{"zh-TW":["清單；列表","列出"],"en":["a series of items written together","to write items in a list"]}', NULL, 'waiting list / mailing list / list requirements', '[{"en":"Please add this task to the priority list.","zh-TW":"請將此任務添加到優先清單中。"},{"en":"The report lists all the recommendations.","zh-TW":"報告列出了所有建議。"}]', '{"noun":"list, listing","verb":"list"}', NULL, 1, 3983, NULL),
(3984, 'listen', '/ˈlɪsən/', 'verb', '{"zh-TW":["聽；傾聽"],"en":["to pay attention to sounds"]}', NULL, 'listen carefully / listen to', '[{"en":"Please listen carefully to the instructions.","zh-TW":"請仔細聽說明。"},{"en":"A good manager listens to feedback.","zh-TW":"好的經理會聽取回饋。"}]', '{"verb":"listen","noun":"listener","noun2":"listening"}', NULL, 2, 3984, NULL),
(3985, 'listening skills', '/''lɪsənɪŋ skɪlz/', 'noun', '{"zh-TW":["聆聽技能；傾聽能力"],"en":["the ability to concentrate on and understand what is being communicated"]}', NULL, 'improve listening skills / demonstrate listening skills / strong listening skills', '[{"en":"Strong listening skills help you understand others'' perspectives and respond effectively.","zh-TW":"強大的聆聽技能幫助你理解他人的觀點並有效回應。"},{"en":"Active listening is one of the most important listening skills in a leadership role.","zh-TW":"積極傾聽是領導角色中最重要的聆聽技能之一。"}]', NULL, NULL, 5, 3985, NULL),
(3986, 'listing', '/ˈlɪstɪŋ/', 'noun', '{"zh-TW":["上市物件；房源列表"],"en":["a property advertised for sale or rent"]}', NULL, 'property listing / browse listings', '[{"en":"We found the ideal property through an online listing.","zh-TW":"我們透過線上房源列表找到了理想的房產。"},{"en":"The real estate agent updated all property listings on the website.","zh-TW":"房地產經紀人更新了網站上所有的房源列表。"}]', '{"verb":"list","adjective":"listed"}', NULL, 3, 3986, NULL),
(3987, 'listing price', '/''lɪstɪŋ praɪs/', 'noun', '{"zh-TW":["掛牌價；標價"],"en":["the price at which a property is advertised for sale by the seller"]}', NULL, 'reduce the listing price / above the listing price / accept the listing price', '[{"en":"The house sold for five percent above the listing price.","zh-TW":"這棟房子以高出掛牌價百分之五的價格成交。"},{"en":"Buyers often try to negotiate below the listing price in a slow market.","zh-TW":"在低迷的市場中，買家通常會嘗試以低於掛牌價的價格協商。"}]', NULL, NULL, 5, 3987, NULL),
(3988, 'listing requirements', '/ˈlɪstɪŋ rɪˈkwaɪərməntɪz/', 'noun', '{"zh-TW":["上市要求"],"en":["the conditions a company must meet to be traded on a stock exchange"]}', NULL, 'meet listing requirements / comply with listing requirements', '[{"en":"The company reorganized its board to meet listing requirements.","zh-TW":"公司重組了董事會以滿足上市要求。"},{"en":"Listing requirements include minimum revenue thresholds and governance standards.","zh-TW":"上市要求包括最低收入門檻和治理標準。"}]', NULL, NULL, 5, 3988, NULL),
(3989, 'literacy', '/ˈlɪtərəsi/', 'noun', '{"zh-TW":["識字能力；素養"],"en":["the ability to read and write; competence in a subject"]}', NULL, 'financial/digital/computer literacy', '[{"en":"Digital literacy is an essential skill in the modern workplace.","zh-TW":"數位素養是現代職場的必備技能。"},{"en":"The program aims to improve adult literacy rates.","zh-TW":"該計劃旨在提高成人識字率。"}]', '{"noun":"literacy","adjective":"literate, illiterate"}', NULL, 3, 3989, NULL),
(3990, 'litigation', '/ˌlɪtɪˈɡeɪʃən/', 'noun', '{"zh-TW":["訴訟","訴訟；起訴"],"en":["the process of taking legal action"]}', NULL, 'avoid litigation / pending litigation', '[{"en":"We want to avoid costly litigation.","zh-TW":"我們想避免昂貴的訴訟。"},{"en":"There is pending litigation against the company.","zh-TW":"有未決訴訟針對公司。"},{"en":"The company settled to avoid costly litigation.","zh-TW":"公司為避免昂貴的訴訟而達成了和解。"},{"en":"There is pending litigation against the manufacturer.","zh-TW":"有針對製造商的未決訴訟。"}]', '{"noun":"litigation","verb":"litigate","noun2":"litigant"}', NULL, 4, 3990, NULL),
(3991, 'litigation risk', '/lɪˈtɪɡeɪʃən rɪsk/', 'noun', '{"zh-TW":["訴訟風險"],"en":["the potential for financial loss resulting from involvement in legal proceedings"]}', NULL, 'assess litigation risk / litigation risk disclosure', '[{"en":"The acquisition target had significant undisclosed litigation risk.","zh-TW":"收購目標有重大的未披露訴訟風險。"},{"en":"A well-drafted contract reduces litigation risk by addressing dispute resolution.","zh-TW":"起草良好的合約通過處理爭議解決減少了訴訟風險。"}]', NULL, NULL, 5, 3991, NULL),
(3992, 'little', '/ˈlɪtəl/', 'adjective', '{"zh-TW":["小的；少的"],"en":["small in size","not much"]}', NULL, 'a little / little by little', '[{"en":"We have a little time left.","zh-TW":"我們還有一點時間。"},{"en":"Little by little, sales improved.","zh-TW":"銷售逐漸改善了。"}]', '{"adjective":"little","adverb":"little"}', NULL, 2, 3992, NULL),
(3993, 'live', '/lɪv/', 'verb', '{"zh-TW":["居住；生活；現場的"],"en":["to have one''s home","broadcast in real time"]}', NULL, 'live broadcast / live up to', '[{"en":"The event will be a live broadcast.","zh-TW":"活動將會現場直播。"},{"en":"The product must live up to expectations.","zh-TW":"產品必須達到預期。"}]', '{"verb":"live","adjective":"live","adjective2":"lively","noun":"living","noun2":"livelihood"}', NULL, 1, 3993, NULL),
(3994, 'load', '/loʊd/', 'noun, verb', '{"zh-TW":["負荷；載重量","裝載"],"en":["the amount carried; a burden","to put goods onto a vehicle"]}', NULL, 'heavy load / workload / load cargo', '[{"en":"The truck was carrying a heavy load.","zh-TW":"卡車載著沉重的貨物。"},{"en":"Workers loaded the containers onto the ship.","zh-TW":"工人們把貨櫃裝上船。"}]', '{"noun":"load","verb":"load, unload"}', NULL, 1, 3994, NULL),
(3995, 'load balancing', '/ləʊd ˈbælənsɪŋ/', 'noun', '{"zh-TW":["負載平衡"],"en":["distributing network traffic across multiple servers to improve performance"]}', NULL, 'implement load balancing / load balancing algorithm / dynamic load balancing', '[{"en":"Load balancing ensures no single server becomes overwhelmed with traffic.","zh-TW":"負載平衡確保沒有單個伺服器因流量而超載。"},{"en":"The web application uses load balancing to maintain high availability.","zh-TW":"網路應用程式使用負載平衡來維持高可用性。"}]', '{"verb":"load balance","noun":"load balancer"}', NULL, 5, 3995, NULL),
(3996, 'loading dock', '/''ləʊdɪŋ dɒk/', 'noun', '{"zh-TW":["裝卸碼頭；貨物裝卸站"],"en":["an area at a warehouse or factory where goods are loaded onto or unloaded from vehicles"]}', NULL, 'access the loading dock / busy loading dock / loading dock equipment', '[{"en":"Trucks backed up to the loading dock to unload their cargo.","zh-TW":"卡車倒退到裝卸碼頭卸貨。"},{"en":"The warehouse has four loading docks to handle simultaneous deliveries.","zh-TW":"倉庫有四個裝卸碼頭，可以同時處理多個交付。"}]', NULL, NULL, 4, 3996, NULL),
(3997, 'loan', '/loʊn/', 'noun, verb', '{"zh-TW":["貸款；借款"],"en":["money lent at interest"]}', NULL, 'bank loan / take out a loan / loan application', '[{"en":"She took out a loan to start her business.","zh-TW":"她貸款來創業。"},{"en":"The bank approved our loan application.","zh-TW":"銀行批准了我們的貸款申請。"}]', '{"noun":"loan","verb":"loan"}', NULL, 1, 3997, NULL),
(3998, 'loan agreement', '/loʊn əˈɡriːmənt/', 'noun', '{"zh-TW":["貸款協議"],"en":["a contract between a lender and borrower defining loan terms"]}', NULL, 'sign a loan agreement / loan agreement terms', '[{"en":"The loan agreement specified a 5-year term at 4% interest.","zh-TW":"貸款協議規定了5年期限以4%利率。"},{"en":"Both parties signed the loan agreement after legal review.","zh-TW":"在法律審查後，雙方簽署了貸款協議。"}]', NULL, NULL, 5, 3998, NULL),
(3999, 'loan covenant', '/loʊn ˈkʌvənənt/', 'noun', '{"zh-TW":["貸款契約條款"],"en":["a condition placed on a borrower by the lender in a loan agreement"]}', NULL, 'comply with loan covenants / breach a loan covenant', '[{"en":"Breaching a loan covenant allows the lender to demand early repayment.","zh-TW":"違反貸款契約條款使貸款方可以要求提前還款。"},{"en":"The company maintained all loan covenants throughout the period.","zh-TW":"公司在整個期間維持了所有貸款契約條款。"}]', NULL, NULL, 5, 3999, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(4000, 'loan origination', '/loʊn ˌɒrɪdʒɪˈneɪʃən/', 'noun', '{"zh-TW":["貸款發放；貸款生成"],"en":["the process of creating a new loan from application through to disbursement"]}', NULL, 'automate loan origination / loan origination fee', '[{"en":"Digital loan origination systems reduce approval times from weeks to hours.","zh-TW":"數字化貸款發放系統將審批時間從幾週縮短到幾小時。"},{"en":"Loan origination fees are charged as a percentage of the loan amount.","zh-TW":"貸款發放費用按貸款金額的百分比收取。"}]', NULL, NULL, 5, 4000, NULL),
(4001, 'loan repayment', '/loʊn rɪˈpeɪmənt/', 'noun', '{"zh-TW":["貸款償還"],"en":["the act of returning borrowed money to the lender"]}', NULL, 'make loan repayments / loan repayment schedule', '[{"en":"Monthly loan repayments were structured over 10 years.","zh-TW":"每月貸款還款期設定為10年。"},{"en":"The company prioritized loan repayment to improve its credit rating.","zh-TW":"公司優先償還貸款以改善其信用評級。"}]', NULL, NULL, 5, 4001, NULL),
(4002, 'lobby', '/ˈlɒbi/', 'verb', '{"zh-TW":["遊說","大廳；遊說"],"en":["to try to influence politicians","an entrance hall; a group trying to influence policy"]}', NULL, 'lobby for / lobbying group; hotel lobby / lobby for/against', '[{"en":"They lobbied for stricter gun laws.","zh-TW":"他們遊說推動更嚴格的槍枝法。"},{"en":"The industry lobby is very powerful.","zh-TW":"產業遊說團體非常有力。"},{"en":"Please wait in the hotel lobby.","zh-TW":"請在酒店大廳等候。"},{"en":"Industry groups lobbied against the new regulation.","zh-TW":"行業團體遊說反對新法規。"}]', '{"noun":"lobby","noun2":"lobbyist","verb":"lobby"}', NULL, 2, 4002, NULL),
(4003, 'lobbying', '/ˈlɒbiɪŋ/', 'noun', '{"zh-TW":["遊說"],"en":["the activity of trying to influence legislators or officials to pass or block legislation"]}', NULL, 'corporate lobbying / political lobbying / lobbying group', '[{"en":"Lobbying by pharmaceutical companies influenced the drug pricing legislation.","zh-TW":"製藥公司的遊說影響了藥品定價立法。"},{"en":"Transparency rules require disclosure of lobbying expenditures to the public.","zh-TW":"透明度規則要求向公眾披露遊說支出。"}]', '{"verb":"lobby","noun2":"lobbyist"}', NULL, 3, 4003, NULL),
(4004, 'local', '/ˈloʊkl/', 'adjective, noun', '{"zh-TW":["當地的；本地的","當地居民"],"en":["relating to a particular place","a person living in a particular area"]}', NULL, 'local government/community/business', '[{"en":"We source ingredients from local suppliers.","zh-TW":"我們從當地供應商採購原料。"},{"en":"The festival is supported by the local community.","zh-TW":"這個節日得到當地社區的支持。"}]', '{"noun":"local, locality","adjective":"local","adverb":"locally","verb":"localize"}', NULL, 2, 4004, NULL),
(4005, 'local cuisine', '/''ləʊkəl kwɪˌziːn/', 'noun', '{"zh-TW":["當地美食；地方菜餚"],"en":["the traditional food and cooking style of a particular region or country"]}', NULL, 'try local cuisine / experience local cuisine / authentic local cuisine', '[{"en":"Trying local cuisine is one of the most enjoyable parts of traveling to a new country.","zh-TW":"品嘗當地美食是前往新國家旅行中最令人享受的部分之一。"},{"en":"She documented her food journey to experience authentic local cuisine across Asia.","zh-TW":"她記錄了自己的美食旅程，以體驗整個亞洲的正宗當地美食。"}]', NULL, NULL, 5, 4005, NULL),
(4006, 'locate', '/ˈloʊkeɪt/', 'verb', '{"zh-TW":["定位；找到；設在"],"en":["to find the position of; to establish in a place"]}', NULL, 'locate a file/office / be located in', '[{"en":"Our headquarters is located in downtown Tokyo.","zh-TW":"我們的總部位於東京市中心。"},{"en":"Can you help me locate the missing file?","zh-TW":"你能幫我找到那個遺失的檔案嗎？"}]', '{"noun":"location","verb":"locate","adjective":"located"}', NULL, 2, 4006, NULL),
(4007, 'location', 'loʊˈkeɪʃən', 'noun', '{"zh-TW":["位置；地點","場所"],"en":["a particular place","where something is situated"]}', NULL, 'office location/prime location', '[{"en":"The new office location is very convenient.","zh-TW":"新辦公室位置非常方便。"}]', '{"verb":"locate","adjective":"located"}', NULL, 3, 4007, 151),
(4008, 'locker room', '/''lɒkər ruːm/', 'noun', '{"zh-TW":["更衣室"],"en":["a room where athletes change their clothes and store equipment before and after sporting activities"]}', NULL, 'locker room talk / team locker room / access the locker room', '[{"en":"The team had a motivational meeting in the locker room before the game.","zh-TW":"球隊在比賽前在更衣室舉行了一次鼓舞士氣的會議。"},{"en":"Security cameras are not permitted inside locker rooms to protect privacy.","zh-TW":"出於隱私保護，更衣室內不允許安裝安全攝影機。"}]', NULL, NULL, 4, 4008, NULL),
(4009, 'locker room talk', '/''lɒkər ruːm tɔːk/', 'noun', '{"zh-TW":["更衣室談話；私下談話"],"en":["conversation between teammates in the locker room; informal discussion among athletes"]}', NULL, 'keep locker room talk private / typical locker room talk', '[{"en":"The coach joined the locker room talk to boost team morale before the game.","zh-TW":"教練在比賽前加入更衣室談話，以提振球隊士氣。"},{"en":"Locker room talk can reflect team chemistry and the atmosphere within the squad.","zh-TW":"更衣室談話可以反映球隊的化學反應和球隊內部的氣氛。"}]', NULL, NULL, 5, 4009, NULL),
(4010, 'locus', '/ˈləʊkəs/', 'noun', '{"zh-TW":["中心；核心點（拉丁語）"],"en":["the effective center or focus of something"]}', NULL, 'locus of control / locus of power / locus of innovation', '[{"en":"The university became the locus of innovation in the region.","zh-TW":"大學成為該地區創新的中心。"},{"en":"Understanding the locus of control affects how people respond to challenges.","zh-TW":"了解控制焦點影響人們如何應對挑戰。"}]', NULL, NULL, 2, 4010, NULL),
(4011, 'log', '/lɔːɡ/', 'noun, verb', '{"zh-TW":["記錄；日誌","記錄；登錄"],"en":["an official record of events","to make a record of"]}', NULL, 'log in / activity log / log data', '[{"en":"Please log all incoming calls.","zh-TW":"請記錄所有來電。"},{"en":"The system logs every transaction automatically.","zh-TW":"系統自動記錄每筆交易。"}]', '{"noun":"log","verb":"log"}', NULL, 1, 4011, NULL),
(4012, 'logic', '/ˈlɑːdʒɪk/', 'noun', '{"zh-TW":["邏輯；道理"],"en":["reasoning conducted according to strict principles"]}', NULL, 'follow the logic / business logic / sound logic', '[{"en":"The logic behind the decision is clear.","zh-TW":"這個決定背後的邏輯很清楚。"},{"en":"There is no logic in spending more than we earn.","zh-TW":"花費超過收入是不合邏輯的。"}]', '{"noun":"logic","adjective":"logical","adverb":"logically"}', NULL, 2, 4012, NULL),
(4013, 'logistics', '/ləˈdʒɪstɪks/', 'noun', '{"zh-TW":["物流；後勤"],"en":["the organization of moving goods or people","the detailed coordination of a complex operation"]}', NULL, 'logistics company / supply chain logistics', '[{"en":"We outsource logistics to a specialist firm.","zh-TW":"我們將物流外包給專業公司。"},{"en":"Logistics costs account for 20% of revenue.","zh-TW":"物流成本佔營收的20%。"},{"en":"The logistics of the event were handled by a professional team.","zh-TW":"活動的後勤工作由專業團隊負責。"},{"en":"Our logistics department ensures timely delivery.","zh-TW":"我們的物流部門確保及時交付。"}]', '{"noun":"logistics","adjective":"logistical","adverb":"logistically"}', NULL, 3, 4013, 386),
(4014, 'logistics hub', '/''lɒdʒɪstɪks hʌb/', 'noun', '{"zh-TW":["物流中心；物流樞紐"],"en":["a central location that serves as a major point for the distribution of goods"]}', NULL, 'develop a logistics hub / regional logistics hub / logistics hub infrastructure', '[{"en":"Singapore functions as a global logistics hub due to its strategic location and facilities.","zh-TW":"新加坡因其優越的地理位置和設施而成為全球物流中心。"},{"en":"The new logistics hub will reduce transportation costs for the entire region.","zh-TW":"新的物流中心將降低整個地區的運輸成本。"}]', NULL, NULL, 5, 4014, NULL),
(4015, 'logistics network', '/''lɒdʒɪstɪks ˌnetwɜːrk/', 'noun', '{"zh-TW":["物流網絡"],"en":["the interconnected system of facilities, transportation links, and processes that move goods from origin to destination"]}', NULL, 'build a logistics network / expand logistics network / optimize logistics network', '[{"en":"The company invested heavily in building a reliable global logistics network.","zh-TW":"公司大量投資建立可靠的全球物流網絡。"},{"en":"A robust logistics network enables fast, efficient delivery to customers worldwide.","zh-TW":"強大的物流網絡使全球客戶能夠快速高效地收到貨物。"}]', NULL, NULL, 5, 4015, NULL),
(4016, 'logistics provider', '/ləˈdʒɪstɪks prəˈvaɪdər/', 'noun', '{"zh-TW":["物流供應商"],"en":["a company that handles transportation and warehousing"]}', NULL, 'select a logistics provider / third-party logistics provider', '[{"en":"We switched to a more reliable logistics provider.","zh-TW":"我們換了一家更可靠的物流供應商。"},{"en":"A good logistics provider ensures timely delivery.","zh-TW":"良好的物流供應商確保及時交貨。"}]', NULL, NULL, 5, 4016, NULL),
(4017, 'logo', '/ˈləʊɡəʊ/', 'noun', '{"zh-TW":["標誌；商標圖案"],"en":["a symbol or design identifying a company or brand"]}', NULL, 'design a logo / brand logo', '[{"en":"The company updated its logo to reflect its modern values.","zh-TW":"公司更新了標誌以反映其現代價值觀。"},{"en":"A memorable logo is central to strong brand identity.","zh-TW":"令人難忘的標誌是強大品牌形象的核心。"}]', NULL, NULL, 1, 4017, NULL),
(4018, 'long', '/lɒŋ/', 'adjective', '{"zh-TW":["【主要意義-形容詞/副詞】長的；長時間的","【次要意義-動詞】渴望；切望；強烈希望得到"],"en":["[primary] measuring a great distance or duration","[secondary - verb] to have a strong desire or wish for something"]}', NULL, 'long for / long to do / long-awaited', '[{"en":"The team longed for a resolution to the prolonged contract dispute.","zh-TW":"團隊渴望解決長期的合約糾紛。"},{"en":"Employees longed for more flexible working arrangements.","zh-TW":"員工渴望更靈活的工作安排。"},{"en":"She had long longed for the opportunity to lead her own project.","zh-TW":"她長久以來一直渴望有機會主導自己的專案。"}]', '{"noun":"longing","adjective":"longing"}', '動詞 long for = 「渴望」，是正式書面英語中的高階詞彙，相當於 yearn for，在 TOEIC 閱讀描述員工情感或職涯期望的語境中偶爾出現。', 1, 4018, NULL),
(4019, 'long position', '/lɒŋ pəˈzɪʃən/', 'noun', '{"zh-TW":["多頭部位；買入持倉"],"en":["holding an asset with the expectation its value will rise"]}', NULL, 'take a long position / maintain a long position', '[{"en":"The fund took a long position in technology stocks.","zh-TW":"基金持有科技股的多頭部位。"},{"en":"A long position profits when asset prices rise.","zh-TW":"多頭部位在資產價格上漲時獲利。"}]', '{"opposite":"short position"}', NULL, 5, 4019, NULL),
(4020, 'long-haul', '/lɒŋ hɔːl/', 'adjective', '{"zh-TW":["長途的"],"en":["involving a long journey or flight"]}', NULL, 'long-haul flight / long-haul travel', '[{"en":"Long-haul flights can cause fatigue and discomfort.","zh-TW":"長途飛行可能導致疲勞和不適。"},{"en":"She prefers business class for long-haul journeys.","zh-TW":"她偏好乘坐商務艙進行長途旅行。"}]', NULL, NULL, 3, 4020, NULL),
(4021, 'long-term', '/ˌlɔːŋˈtɜːrm/', 'adjective', '{"zh-TW":["長期的"],"en":["lasting for a long time"]}', NULL, 'long-term plan/goal/investment/strategy', '[{"en":"We need a long-term strategy for growth.","zh-TW":"我們需要一個長期的成長策略。"},{"en":"Long-term investments tend to yield higher returns.","zh-TW":"長期投資往往能帶來更高的回報。"}]', '{"adjective":"long-term"}', NULL, 3, 4021, NULL),
(4022, 'long-term contract', '/lɒŋ tɜːrm ˈkɒntrækt/', 'noun', '{"zh-TW":["長期合約"],"en":["an agreement covering a period typically exceeding one year"]}', NULL, 'negotiate a long-term contract / long-term contract benefits', '[{"en":"A long-term contract with the supplier locks in favorable pricing.","zh-TW":"與供應商的長期合約鎖定了有利的定價。"},{"en":"Long-term contracts provide revenue stability for service providers.","zh-TW":"長期合約為服務提供商提供了收入穩定性。"}]', NULL, NULL, 5, 4022, NULL),
(4023, 'long-term debt', '/lɒŋ tɜːrm det/', 'noun', '{"zh-TW":["長期債務"],"en":["debt obligations with maturities extending beyond one year"]}', NULL, 'carry long-term debt / reduce long-term debt / long-term debt repayment', '[{"en":"The company refinanced its long-term debt at lower interest rates.","zh-TW":"公司以較低的利率再融資了長期債務。"},{"en":"Managing long-term debt is crucial for financial stability.","zh-TW":"管理長期債務對財務穩定至關重要。"}]', NULL, NULL, 5, 4023, NULL),
(4024, 'long-term investment', '/lɒŋ tɜːrm ɪnˈvestmənt/', 'noun', '{"zh-TW":["長期投資"],"en":["an asset or capital allocation held for more than one year to generate returns"]}', NULL, 'hold as a long-term investment / long-term investment returns', '[{"en":"Property is often classified as a long-term investment on the balance sheet.","zh-TW":"房地產通常在資產負債表上被歸類為長期投資。"},{"en":"Long-term investments require patience but typically provide higher returns.","zh-TW":"長期投資需要耐心，但通常提供更高的回報。"}]', NULL, NULL, 5, 4024, NULL),
(4025, 'long-term liability', '/lɒŋ tɜːrm ˌlaɪəˈbɪlɪti/', 'noun', '{"zh-TW":["長期負債"],"en":["a financial obligation not due within the current accounting year"]}', NULL, 'report long-term liabilities / reduce long-term liabilities', '[{"en":"Long-term liabilities include bonds payable and pension obligations.","zh-TW":"長期負債包括應付債券和養老金義務。"},{"en":"Investors assess long-term liabilities when evaluating a company''s solvency.","zh-TW":"投資者在評估公司的償付能力時評估長期負債。"}]', '{"opposite":"current liability"}', NULL, 5, 4025, NULL),
(4026, 'longitudinal', '/ˌlɒndʒɪˈtjuːdɪnəl/', 'adjective', '{"zh-TW":["縱向的；長期的"],"en":["relating to the development of the same person or thing over time"]}', NULL, 'longitudinal study / longitudinal data / longitudinal research', '[{"en":"A longitudinal study tracked participants over twenty years.","zh-TW":"縱向研究跟蹤了二十年的參與者。"},{"en":"Longitudinal data allows researchers to observe changes and trends.","zh-TW":"縱向數據允許研究員觀察變化和趨勢。"}]', '{"adverb":"longitudinally"}', NULL, 4, 4026, NULL),
(4027, 'look', '/lʊk/', 'verb', '{"zh-TW":["看；看起來"],"en":["to direct eyes toward","to seem"]}', NULL, 'look forward to / look into', '[{"en":"I look forward to your reply.","zh-TW":"我期待你的回覆。"},{"en":"We will look into this matter.","zh-TW":"我們會調查此事。"}]', '{"verb":"look","noun":"look","noun2":"outlook"}', NULL, 1, 4027, NULL),
(4028, 'lose', '/luːz/', 'verb', '{"zh-TW":["失去；輸"],"en":["to no longer have","to fail to win"]}', NULL, 'lose money / lose track', '[{"en":"We cannot afford to lose this client.","zh-TW":"我們不能失去這個客戶。"},{"en":"Don''t lose track of expenses.","zh-TW":"不要忽略了開支。"}]', '{"verb":"lose","noun":"loss","noun2":"loser","adjective":"lost"}', NULL, 1, 4028, NULL),
(4029, 'loss', '/lɔːs/', 'noun', '{"zh-TW":["損失；虧損"],"en":["the state of no longer having something; financial deficit"]}', NULL, 'profit and loss / at a loss / job losses', '[{"en":"The company reported a net loss of $5 million.","zh-TW":"公司報告了500萬美元的淨虧損。"},{"en":"The loss of key personnel affected productivity.","zh-TW":"關鍵人員的流失影響了生產力。"}]', '{"noun":"loss","verb":"lose","adjective":"lost"}', NULL, 1, 4029, 387),
(4030, 'loss aversion', '/lɒs əˈvɜːrʒən/', 'noun', '{"zh-TW":["損失厭惡"],"en":["a tendency to prefer avoiding losses over acquiring equivalent gains"]}', NULL, 'overcome loss aversion / loss aversion bias', '[{"en":"Loss aversion can prevent investors from selling underperforming assets.","zh-TW":"損失厭惡可能阻止投資者出售績效不佳的資產。"},{"en":"Understanding loss aversion is important for financial advisors.","zh-TW":"了解損失厭惡對財務顧問至關重要。"}]', NULL, NULL, 5, 4030, NULL),
(4031, 'loss leader', '/lɒs ˈliːdər/', 'noun', '{"zh-TW":["虧本誘客商品"],"en":["a product sold at a loss to attract customers who then buy other profitable items"]}', NULL, 'use a loss leader strategy / loss leader pricing', '[{"en":"The supermarket used milk as a loss leader to drive foot traffic.","zh-TW":"超市使用牛奶作為虧本誘客商品來吸引客流。"},{"en":"A loss leader strategy sacrifices margin on one product to grow overall sales.","zh-TW":"虧本誘客商品策略犧牲一種產品的利潤以增加整體銷售額。"}]', NULL, NULL, 4, 4031, NULL),
(4032, 'loss leader pricing', '/lɒs ˈliːdər ˈpraɪsɪŋ/', 'noun', '{"zh-TW":["虧本定價；低於成本定價"],"en":["selling a product below cost to attract customers who buy other profitable items"]}', NULL, 'use loss leader pricing / loss leader pricing strategy', '[{"en":"The retailer used loss leader pricing on milk to drive foot traffic.","zh-TW":"零售商對牛奶使用虧本定價以增加客流量。"},{"en":"Loss leader pricing is effective when combined with high-margin add-ons.","zh-TW":"當與高利潤附加品結合時，虧本定價很有效。"}]', NULL, NULL, 5, 4032, NULL),
(4033, 'loss of earnings', '/lɒs əv ˈɜːrnɪŋz/', 'noun', '{"zh-TW":["收入損失"],"en":["a reduction in income resulting from business disruption or injury"]}', NULL, 'claim for loss of earnings / loss of earnings compensation', '[{"en":"The storm caused a loss of earnings of 2 million for the business.","zh-TW":"風暴給企業造成了200萬元的收入損失。"},{"en":"The insurance policy covers loss of earnings during business interruption.","zh-TW":"保險政策涵蓋業務中斷期間的收入損失。"}]', NULL, NULL, 5, 4033, NULL),
(4034, 'loss provision', '/lɒs prəˈvɪʒən/', 'noun', '{"zh-TW":["損失準備金"],"en":["funds set aside to cover expected future losses"]}', NULL, 'create a loss provision / draw on a loss provision', '[{"en":"The bank increased its loss provision for bad loans.","zh-TW":"銀行增加了壞帳損失準備金。"},{"en":"A large loss provision reduced the reported profit significantly.","zh-TW":"大額損失準備金顯著降低了報告利潤。"}]', NULL, NULL, 5, 4034, NULL),
(4035, 'loss ratio', '/lɒs ˈreɪʃioʊ/', 'noun', '{"zh-TW":["賠付率；損失比率"],"en":["the ratio of insurance claims paid to premiums earned"]}', NULL, 'calculate loss ratio / high loss ratio', '[{"en":"A loss ratio above 100% means the insurer is paying out more than it earns.","zh-TW":"高於100%的賠付率意味著保險公司的賠付超過了其收入。"},{"en":"The insurer reviewed its underwriting criteria after a high loss ratio.","zh-TW":"保險公司在賠付率高之後審查了其承保標準。"}]', NULL, NULL, 4, 4035, NULL),
(4036, 'lost and found', '/lɒst ænd faʊnd/', 'noun', '{"zh-TW":["失物招領處"],"en":["a place where lost items are stored and returned"]}', NULL, 'report to lost and found / check the lost and found', '[{"en":"He reported his missing bag to the lost and found.","zh-TW":"他向失物招領處報告了他遺失的包。"},{"en":"Check the airport lost and found for misplaced items.","zh-TW":"請在機場失物招領處查詢遺失物品。"}]', NULL, NULL, 5, 4036, NULL),
(4037, 'lost luggage', '/''lɒst ˈlʌɡɪdʒ/', 'noun', '{"zh-TW":["行李遺失；丟失的行李"],"en":["baggage that has been misplaced or not delivered to its destination by an airline"]}', NULL, 'report lost luggage / lost luggage claim / locate lost luggage', '[{"en":"She filed a lost luggage report at the airline''s service counter.","zh-TW":"她在航空公司服務台提交了行李遺失報告。"},{"en":"The airline compensated her for the lost luggage after three days of searching.","zh-TW":"在尋找三天後，航空公司賠償了她的遺失行李。"}]', NULL, NULL, 4, 4037, NULL),
(4038, 'loud', '/laʊd/', 'adjective', '{"zh-TW":["大聲的"],"en":["producing much noise"]}', NULL, 'loud and clear / think out loud', '[{"en":"The message came through loud and clear.","zh-TW":"訊息傳達得非常清楚。"},{"en":"Let me think out loud for a moment.","zh-TW":"讓我大聲想一下。"}]', '{"adjective":"loud","adverb":"loudly","noun":"loudness"}', NULL, 1, 4038, NULL),
(4039, 'lounge', '/laʊndʒ/', 'noun, verb', '{"zh-TW":["休息室；候機室"],"en":["a room for relaxing; an airport waiting area"]}', NULL, 'departure lounge / VIP lounge / executive lounge', '[{"en":"Please wait in the departure lounge.","zh-TW":"請在候機室等候。"},{"en":"The hotel has an executive lounge for business guests.","zh-TW":"酒店有商務客人專屬的行政酒廊。"}]', '{"noun":"lounge","verb":"lounge"}', NULL, 2, 4039, NULL),
(4040, 'lounge access', '/''laʊndʒ ˈækses/', 'noun', '{"zh-TW":["休息室使用權；貴賓室進入資格"],"en":["the privilege of entering an airport or hotel lounge facility"]}', NULL, 'complimentary lounge access / lounge access included / lounge access card', '[{"en":"Her premium credit card included complimentary lounge access at major airports.","zh-TW":"她的白金信用卡包含在主要機場的免費休息室使用權。"},{"en":"Lounge access can be purchased for a day pass even without elite status.","zh-TW":"即使沒有精英會員身份，也可以購買一日通行證使用休息室。"}]', NULL, NULL, 5, 4040, NULL),
(4041, 'love', '/lʌv/', 'verb', '{"zh-TW":["愛；喜愛"],"en":["to have strong affection for","to like very much"]}', NULL, 'love to / labor of love', '[{"en":"Customers love our new product.","zh-TW":"客戶很喜歡我們的新產品。"},{"en":"Building this app was a labor of love.","zh-TW":"開發這個應用程式是出於熱愛。"}]', '{"verb":"love","noun":"love","adjective":"lovely","adjective2":"lovable"}', NULL, 1, 4041, NULL),
(4042, 'low', '/loʊ/', 'adjective', '{"zh-TW":["低的"],"en":["below the usual level","not high"]}', NULL, 'low cost / low risk', '[{"en":"We offer low-cost solutions.","zh-TW":"我們提供低成本方案。"},{"en":"This is a low-risk investment.","zh-TW":"這是低風險投資。"}]', '{"adjective":"low","verb":"lower","noun":"low","adverb":"low"}', NULL, 1, 4042, NULL),
(4043, 'low-carbon', '/ˌləʊ ˈkɑːrbən/', 'adjective', '{"zh-TW":["低碳的"],"en":["producing a relatively small amount of carbon dioxide"]}', NULL, 'low-carbon economy / low-carbon solution', '[{"en":"The government promotes a transition to a low-carbon economy.","zh-TW":"政府促進向低碳經濟轉型。"},{"en":"Low-carbon technologies reduce the impact of climate change.","zh-TW":"低碳技術減少了氣候變遷的影響。"}]', NULL, NULL, 4, 4043, NULL),
(4044, 'low-carbon economy', '/ləʊ ˈkɑːrbən ɪˈkɒnəmi/', 'noun', '{"zh-TW":["低碳經濟"],"en":["an economy based on low-carbon energy sources to minimize CO₂ emissions"]}', NULL, 'transition to a low-carbon economy / low-carbon economy growth / invest in low-carbon economy', '[{"en":"The EU is investing trillions to build a low-carbon economy.","zh-TW":"歐盟正在投入數萬億美元建立低碳經濟。"},{"en":"A low-carbon economy creates jobs in renewable energy and efficiency sectors.","zh-TW":"低碳經濟在可再生能源和效率部門創造就業機會。"}]', NULL, NULL, 5, 4044, NULL),
(4045, 'low-cost', '/loʊ kɒst/', 'adjective', '{"zh-TW":["低成本的"],"en":["involving or requiring little expenditure"]}', NULL, 'low-cost airline / low-cost production / low-cost alternative', '[{"en":"The company launched a low-cost line to capture budget-conscious customers.","zh-TW":"公司推出了低成本產品線以吸引注重預算的客戶。"},{"en":"Low-cost providers compete primarily on price rather than quality.","zh-TW":"低成本提供商主要在價格而非品質上競爭。"}]', NULL, NULL, 3, 4045, NULL),
(4046, 'low-fat', '/''ləʊ fæt/', 'adjective', '{"zh-TW":["低脂的；低脂肪的"],"en":["containing a small amount of fat, especially as a dietary choice"]}', NULL, 'low-fat diet / low-fat dairy / low-fat option', '[{"en":"Low-fat yogurt is popular among people watching their calorie intake.","zh-TW":"低脂優格在注意卡路里攝取的人中很受歡迎。"},{"en":"The nutritionist recommended switching to low-fat dairy products.","zh-TW":"營養師建議改用低脂乳製品。"}]', NULL, NULL, 3, 4046, NULL),
(4047, 'low-hanging fruit', '/loʊ ˈhæŋɪŋ fruːt/', 'noun', '{"zh-TW":["容易達成的目標；唾手可得的機會"],"en":["the easiest and most immediate opportunities for improvement"]}', NULL, 'identify low-hanging fruit / target low-hanging fruit', '[{"en":"The consultant identified low-hanging fruit to improve profitability quickly.","zh-TW":"顧問識別了迅速改善盈利能力的容易達成的目標。"},{"en":"Cost savings from low-hanging fruit were realized within the first month.","zh-TW":"第一個月內實現了來自容易達成目標的成本節省。"}]', NULL, NULL, 5, 4047, NULL),
(4048, 'lower breakeven', '/loʊər ˈbreɪkˌiːvən/', 'verb', '{"zh-TW":["降低損益平衡點"],"en":["to reduce the minimum level of sales needed to cover costs"]}', NULL, 'work to lower breakeven / successfully lower the breakeven', '[{"en":"Cutting fixed costs helped the company lower its breakeven point.","zh-TW":"削減固定成本幫助公司降低了損益平衡點。"},{"en":"The restructuring was designed to lower the breakeven quickly.","zh-TW":"重組旨在快速降低損益平衡點。"}]', NULL, NULL, 5, 4048, NULL),
(4049, 'loyal', '/ˈlɔɪəl/', 'adjective', '{"zh-TW":["忠誠的；忠實的"],"en":["giving firm support to someone or something"]}', NULL, 'loyal customer/employee / remain loyal', '[{"en":"We value our loyal customers.","zh-TW":"我們重視忠實客戶。"},{"en":"She remained loyal to the company for 20 years.","zh-TW":"她對公司忠誠了20年。"}]', '{"noun":"loyalty","adjective":"loyal","adverb":"loyally"}', NULL, 2, 4049, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(4050, 'loyalty', 'ˈlɔɪəlti', 'noun', '{"zh-TW":["忠誠；忠心","客戶忠誠度"],"en":["dedication to a person or cause","customer faithfulness"]}', NULL, 'customer loyalty/brand loyalty', '[{"en":"Customer loyalty programs drive retention.","zh-TW":"客戶忠誠計畫推動留存率。"}]', '{"adjective":"loyal","adverb":"loyally"}', NULL, 3, 4050, 388),
(4051, 'loyalty points', '/ˈlɔɪəlti pɔɪnts/', 'noun', '{"zh-TW":["忠誠度積分"],"en":["points earned in a loyalty program that can be redeemed for rewards"]}', NULL, 'earn loyalty points / redeem loyalty points', '[{"en":"She earned enough loyalty points for a free night.","zh-TW":"她積累了足夠的忠誠度積分兌換免費一晚住宿。"},{"en":"Loyalty points expire if not used within two years.","zh-TW":"忠誠度積分若兩年內未使用則到期失效。"}]', NULL, NULL, 5, 4051, NULL),
(4052, 'loyalty program', '/ˈlɔɪəlti ˈproʊɡræm/', 'noun', '{"zh-TW":["忠誠度計劃；會員計劃"],"en":["a reward program encouraging repeat business from customers"]}', NULL, 'launch a loyalty program / join the loyalty program / loyalty program rewards', '[{"en":"The loyalty program increased repeat purchase rates by 35%.","zh-TW":"忠誠度計劃使重複購買率提高了35%。"},{"en":"Customers earn points through the loyalty program with each purchase.","zh-TW":"客戶通過忠誠度計劃每次購買都能獲得積分。"}]', '{"adjective":"loyalty-based"}', NULL, 5, 4052, NULL),
(4053, 'lucid', '/ˈluːsɪd/', 'adjective', '{"zh-TW":["清晰的；易懂的"],"en":["expressed clearly; easy to understand"]}', NULL, 'lucid explanation / lucid writing / lucid argument', '[{"en":"Her lucid explanation made the complex topic accessible to everyone.","zh-TW":"她清晰的解釋使複雜的主題對所有人都易於理解。"},{"en":"A lucid abstract helps readers quickly assess a paper''s relevance.","zh-TW":"清晰的摘要幫助讀者快速評估論文的相關性。"}]', '{"adverb":"lucidly","noun":"lucidity"}', NULL, 2, 4053, NULL),
(4054, 'luck', '/lʌk/', 'noun', '{"zh-TW":["運氣"],"en":["good or bad things that happen by chance"]}', NULL, 'good luck / out of luck', '[{"en":"Good luck with your presentation!","zh-TW":"祝你簡報順利！"},{"en":"We are out of luck with this supplier.","zh-TW":"我們跟這個供應商運氣不好。"}]', '{"noun":"luck","adjective":"lucky","adverb":"luckily","adjective2":"unlucky"}', NULL, 1, 4054, NULL),
(4055, 'lucrative', '/ˈluːkrətɪv/', 'adjective', '{"zh-TW":["有利可圖的；賺錢的"],"en":["producing a large amount of profit"]}', NULL, 'lucrative business/deal/market/contract', '[{"en":"The overseas market proved highly lucrative.","zh-TW":"海外市場被證明是非常有利可圖的。"},{"en":"She landed a lucrative consulting contract.","zh-TW":"她獲得了一份利潤豐厚的顧問合同。"}]', '{"adjective":"lucrative"}', NULL, 3, 4055, NULL),
(4056, 'luggage', '/ˈlʌɡɪdʒ/', 'noun', '{"zh-TW":["行李"],"en":["suitcases or bags used when traveling"]}', NULL, 'carry-on luggage / check luggage / luggage allowance', '[{"en":"Please keep your luggage with you at all times.","zh-TW":"請隨時注意您的行李。"},{"en":"The airline lost my luggage.","zh-TW":"航空公司弄丟了我的行李。"}]', '{"noun":"luggage"}', NULL, 3, 4056, NULL),
(4057, 'luggage allowance', '/ˈlʌɡɪdʒ əˈlaʊəns/', 'noun', '{"zh-TW":["行李限額"],"en":["the maximum weight or number of bags permitted on a flight without extra charge"]}', NULL, 'exceed the luggage allowance / check luggage allowance', '[{"en":"Business class offers a more generous luggage allowance than economy.","zh-TW":"商務艙提供比經濟艙更寬鬆的行李限額。"},{"en":"She paid an excess fee because she exceeded the luggage allowance.","zh-TW":"她因超出行李限額而支付了超重費。"}]', NULL, NULL, 5, 4057, NULL),
(4058, 'luggage storage', '/''lʌɡɪdʒ ˌstɔːrɪdʒ/', 'noun', '{"zh-TW":["行李寄存；行李存放"],"en":["a service offering temporary storage of luggage at a station, airport, or hotel"]}', NULL, 'use luggage storage / luggage storage facility / pay for luggage storage', '[{"en":"She left her bags at the train station''s luggage storage to explore the city hands-free.","zh-TW":"她把行李放在火車站的行李寄存處，以便輕鬆探索城市。"},{"en":"The hotel offered complimentary luggage storage for guests who checked out early.","zh-TW":"飯店為提前退房的客人提供免費行李寄存服務。"}]', NULL, NULL, 5, 4058, NULL),
(4059, 'luggage tag', '/ˈlʌɡɪdʒ tæɡ/', 'noun', '{"zh-TW":["行李標籤"],"en":["a label attached to luggage with identification details"]}', NULL, 'attach a luggage tag / luggage tag information', '[{"en":"Always attach a luggage tag to your checked bags.","zh-TW":"務必在託運行李上附上行李標籤。"},{"en":"The luggage tag helped identify her bag at baggage claim.","zh-TW":"行李標籤幫助她在行李提領處識別她的行李。"}]', NULL, NULL, 4, 4059, NULL),
(4060, 'lump', '/lʌmp/', 'noun, adjective', '{"zh-TW":["一次性的；塊"],"en":["a compact mass; paid in one amount"]}', NULL, 'lump sum / lump together', '[{"en":"He received a lump sum payment upon retirement.","zh-TW":"他退休時收到了一次性付款。"},{"en":"Don''t lump all the expenses together.","zh-TW":"不要把所有費用混在一起。"}]', '{"noun":"lump","verb":"lump","adjective":"lump-sum"}', NULL, 1, 4060, NULL),
(4061, 'lump sum', '/lʌmp sʌm/', 'noun', '{"zh-TW":["一次性付款；整筆款項"],"en":["a single large payment made at one time"]}', NULL, 'pay a lump sum / lump sum payment', '[{"en":"She chose to receive her pension as a lump sum.","zh-TW":"她選擇以一次性付款的方式領取養老金。"},{"en":"A lump sum payment was made to settle the debt in full.","zh-TW":"一次性付款用於全額結清債務。"}]', NULL, NULL, 3, 4061, NULL),
(4062, 'lump sum contract', '/lʌmp sʌm ˈkɒntrækt/', 'noun', '{"zh-TW":["總額合約；固定總價合約"],"en":["a contract where a fixed price is agreed for the entire scope of work"]}', NULL, 'award a lump sum contract / lump sum contract risks', '[{"en":"The construction firm won a lump sum contract worth $5 million.","zh-TW":"建築公司贏得了價值500萬元的總額合約。"},{"en":"A lump sum contract places cost risk on the contractor to deliver within budget.","zh-TW":"總額合約將成本風險置於承包商身上，要求其在預算內交付。"}]', '{"synonym":"fixed-price contract"}', NULL, 5, 4062, NULL),
(4063, 'lump sum payment', '/lʌmp sʌm ˈpeɪmənt/', 'noun', '{"zh-TW":["一次性付款"],"en":["a single payment for the entire amount due, rather than in instalments"]}', NULL, 'make a lump sum payment / lump sum payment option', '[{"en":"The client chose a lump sum payment to avoid ongoing monthly fees.","zh-TW":"客戶選擇一次性付款以避免持續的月費。"},{"en":"A lump sum payment may attract a discount from the supplier.","zh-TW":"一次性付款可能從供應商那裡獲得折扣。"}]', NULL, NULL, 5, 4063, NULL),
(4064, 'lump-sum payment', '/lʌmp sʌm ˈpeɪmənt/', 'noun', '{"zh-TW":["一次性付款"],"en":["a single large payment made at one time rather than in installments"]}', NULL, 'make a lump-sum payment / lump-sum settlement', '[{"en":"The employee chose a lump-sum payment instead of monthly pension installments.","zh-TW":"員工選擇了一次性付款而不是每月養老金分期付款。"},{"en":"The contract was settled with a lump-sum payment of $500,000.","zh-TW":"合約以50萬元的一次性付款了結了。"}]', '{"opposite":"installment payment"}', NULL, 5, 4064, NULL),
(4065, 'luxury', '/ˈlʌkʃəri/', 'noun, adjective', '{"zh-TW":["奢侈品；奢華"],"en":["great comfort and expensive things"]}', NULL, 'luxury goods/brand/hotel / afford the luxury', '[{"en":"Luxury goods sales have increased in Asia.","zh-TW":"亞洲的奢侈品銷售額有所增長。"},{"en":"They stayed at a luxury hotel.","zh-TW":"他們住在一家豪華酒店。"}]', '{"noun":"luxury","adjective":"luxurious"}', NULL, 2, 4065, NULL),
(4066, 'machine', '/məˈʃiːn/', 'noun', '{"zh-TW":["機器"],"en":["a device that performs a task"]}', NULL, 'machine learning / vending machine', '[{"en":"Machine learning is transforming business.","zh-TW":"機器學習正在改變商業。"},{"en":"The vending machine is in the lobby.","zh-TW":"自動販賣機在大廳。"}]', '{"noun":"machine","noun2":"machinery","noun3":"machinist"}', NULL, 3, 4066, NULL),
(4067, 'machine learning', '/məˈʃiːn ˈlɜːrnɪŋ/', 'noun', '{"zh-TW":["機器學習"],"en":["a type of AI where systems learn and improve from data without explicit programming"]}', NULL, 'machine learning model / apply machine learning / machine learning algorithm', '[{"en":"Machine learning models improved fraud detection accuracy.","zh-TW":"機器學習模型提高了欺詐偵測的準確性。"},{"en":"The recommendation engine uses machine learning to personalize content.","zh-TW":"推薦引擎使用機器學習來個人化內容。"}]', '{"abbreviation":"ML","adjective":"machine-learning"}', NULL, 5, 4067, NULL),
(4068, 'machine learning model', '/məˈʃiːn ˈlɜːrnɪŋ ˈmɒdəl/', 'noun', '{"zh-TW":["機器學習模型"],"en":["a mathematical model trained on data to make predictions or decisions"]}', NULL, 'train a machine learning model / deploy a machine learning model / evaluate a machine learning model', '[{"en":"The machine learning model predicts customer churn with eighty percent accuracy.","zh-TW":"機器學習模型以百分之八十的準確率預測客戶流失。"},{"en":"Retraining the machine learning model with new data improved its performance.","zh-TW":"用新數據重新訓練機器學習模型提高了其性能。"}]', NULL, NULL, 5, 4068, NULL),
(4069, 'machinery', '/məˈʃiːnəri/', 'noun', '{"zh-TW":["機械；機器設備"],"en":["machines collectively; the components of a machine"]}', NULL, 'heavy/industrial machinery', '[{"en":"The factory invested in new machinery.","zh-TW":"工廠投資了新機器設備。"},{"en":"Heavy machinery is used in construction.","zh-TW":"重型機械用於建築工程。"}]', '{"noun":"machinery, machine","verb":"machine"}', NULL, 3, 4069, NULL),
